(295, 'development_program', NULL, '2025-12-26 04:01:01', 'Dilibatkan dalam project peningkatan kinerja dengan anggota tim dari unit/bagian berbeda', NULL, '8'),
(297, 'development_program', NULL, '2025-12-26 04:00:33', 'Diajak berdiskusi mengenai aktivitas team bulding, teamwork maupun handling group conflict, setelah itu terapkan pengetahuan yang telah didiskusikan dalam pekerjaan sehari-hari', NULL, '9'),
(298, 'development_program', NULL, '2025-11-24 20:32:17', 'Dilibatkan dalam kelompok dengan variasi latar belakang maupun lintas fungsi, agar terlatih untuk memberikan ide maupun pendapat bagi kelompok', NULL, '8'),
(299, 'development_program', NULL, '2025-11-24 20:58:51', 'Team Facilitation & Communication', NULL, '10'),
(301, 'development_program', NULL, '2025-11-24 23:17:06', 'Memfasilitasi perselisihan dan konflik yang terjadi di lingkungan kerja guna menjaga produktivitas dan keharmonisan tim', NULL, '9'),
(303, 'development_program', NULL, '2025-11-24 19:52:36', 'Berpartisipasi dalam proyek di mana asesi punya kesempatan memimpin tim dengan latar belakang serta karakter yang berbeda', NULL, '8'),
(304, 'development_program', NULL, '2025-11-24 21:00:23', 'Secara berkala mengadakan forum diskusi dengan tim yang dipimpin untuk memberikan umpan balik yang konstruktif guna mendorong peningkatan kinerja tim yang lebih signifikan', NULL, '8'),
(305, 'development_program', NULL, '2025-11-24 20:56:29', 'Leading by Example in Teams', NULL, '10'),
(306, 'development_program', NULL, '2025-12-26 04:02:45', 'Brainstorming dengan atasan mengenai metode terbaik untuk berbagi pengetahuan dalam tim, dan mendiskusikan cara memfasilitasi knowledge sharing sessions secara terstruktur', NULL, '9'),
(307, 'development_program', NULL, '2025-11-24 23:29:13', 'Mengadakan diskusi dengan anggota tim untuk memahami aspirasi mereka serta menyusun rencana pengembangan kompetensi, termasuk melakukan pemantauan terhadap kemajuan yang dicapai', NULL, '8'),
(308, 'development_program', NULL, '2025-11-24 20:11:10', 'Company Values & Ethical Practices', NULL, '10'),
(309, 'development_program', NULL, '2025-11-25 00:42:50', 'Memberikan feedback secara langsung terhadap perilaku sehari-hari yang ditunjukkan oleh asesi baik yang sudah sesuai norma ataupun tidak', NULL, '9'),
(310, 'development_program', NULL, '2025-12-26 04:00:50', 'Mempelajari cara-cara efektif atau pendekatan yang sesuai dalam berpartisipasi dalam tim', NULL, '9'),
(311, 'development_program', NULL, '2025-11-24 20:04:30', 'Building & Sustaining a Culture of Integrity', NULL, '10'),
(312, 'development_program', NULL, '2025-11-25 00:43:22', 'Mempelajari cara efektif untuk mengingatkan rekan/tim mengenai nilai-nilai organisasi, serta keberanian bertindak tegas dalam menerapkan sikap kerja berintegritas', NULL, '9'),
(313, 'development_program', NULL, '2025-11-24 21:00:38', 'Melatih berkata jujur kepada orang lain yang menunjukkan perilaku yang tidak sesuai dengan norma perusahaan, serta terbuka terhadap umpan balik yang diberikan orang lain', NULL, '8'),
(314, 'development_program', NULL, '2025-11-24 20:56:16', 'Integrity Education & Ethical Conflict Management', NULL, '10'),
(315, 'development_program', NULL, '2025-11-25 00:44:03', 'Bersikap asertif dan mengedukasi/menegur pihak-pihak yang melakukan pelanggaran serta menyusun langkah antisipasi agar tidak terjadi pelanggaran berulang', NULL, '9'),
(316, 'development_program', NULL, '2025-12-30 09:27:07', 'Melakukan job shadowing untuk memahami bagaimana atasan bersikap tegas terhadap personel yang melanggar aturan kerja', NULL, '8'),
(317, 'development_program', NULL, '2025-11-24 23:16:11', 'Membuat kesepakatan aturan di antara rekan antar unit dalam menyikapi pelanggaran', NULL, '8'),
(318, 'development_program', NULL, '2025-11-24 20:05:05', 'Building a Culture of Integrity in Leadership', NULL, '10'),
(319, 'development_program', NULL, '2025-11-24 20:15:24', 'Diberikan arahan mengenai langkah untuk mensosialisasikan kebijakan dan menjaga kepatuhan tim terhadap aturan organisasi', NULL, '9'),
(320, 'development_program', NULL, '2025-11-24 23:48:54', 'Merancang dan mengimplementasikan program ethical leadership yang memastikan semua pemimpin tim menjadi role model dalam menjaga integritas', NULL, '8'),
(321, 'development_program', NULL, '2025-11-24 20:30:19', 'Winning Together as a Team', NULL, '10'),
(322, 'development_program', NULL, '2025-11-24 23:47:46', 'Menginisiasi hubungan kerja sama dengan berbagai pihak yang memperhatikan kepentingan kedua belah pihak', NULL, '9'),
(323, 'development_program', NULL, '2025-11-24 23:41:43', 'Menghargai perbedaan pendapat dan mengedepankan win-win solution untuk menjaga harmonisasi tim kerja', NULL, '9'),
(324, 'development_program', NULL, '2025-12-26 04:13:50', 'Memimpin atau berkontribusi dalam sebuah proyek lintas tim yang membutuhkan sinergi dan koordinasi dengan rekan kerja, dan menerapkan prinsip \"win-win solution\" dengan memastikan bahwa setiap anggota tim mendapat manfaat dari kontribusi kolektif', NULL, '8'),
(325, 'development_program', NULL, '2025-11-24 20:55:44', 'Harmony Environment', NULL, '10'),
(326, 'development_program', NULL, '2025-12-26 04:14:55', 'Menginisiasi strategi bisnis menjadi program kerja operasional yang dapat dijalankan oleh tim berdasarkan visi perusahaan, menyusun target dan langkah-langkah strategis yang dapat diterapkan dalam tim', NULL, '9'),
(327, 'development_program', NULL, '2025-11-24 21:01:10', 'Membaca buku atau mengikuti forum diskusi untuk menambah wawasan dalam menyusun rencana pengembangan subordinat serta mendorong mereka menghasilkan alternatif solusi bagi persoalan di unit kerja', NULL, '8'),
(328, 'development_program', NULL, '2025-12-26 04:18:10', 'Creating a Harmonious & Goal-Oriented Team', NULL, '10'),
(329, 'development_program', NULL, '2025-11-24 23:40:17', 'Mengatasi konflik yang muncul dalam tim, serta mempelajari cara menjaga harmonisasi hubungan tim', NULL, '9'),
(330, 'development_program', NULL, '2025-11-24 03:31:03', 'Arahan mengenai pentingnya menciptakan suasana kerja yang harmonis guna mendukung pencapaian sasaran jangka panjang perusahaan', NULL, '9'),
(331, 'development_program', NULL, '2025-12-26 04:15:28', 'Dapat membahas dan memberikan diskusi lebih terkait target jangka panjang organisasi dan peran tim kerja di dalamnya', NULL, '9'),
(332, 'development_program', NULL, '2025-11-24 19:53:17', 'Berpartisipasi dalam seminar, workshop, atau forum terkait manajemen konflik dan pengelolaan tim guna meningkatkan keterampilan dalam menjembatani perbedaan pendapat', NULL, '8'),
(333, 'development_program', NULL, '2025-11-24 23:28:30', 'Mendokumentasikan dan menganalisis pendekatan yang digunakan dalam penyelesaian konflik serta menyusun strategi untuk diterapkan dalam peran kepemimpinan sendiri', NULL, '8'),
(334, 'development_program', NULL, '2025-11-24 19:53:46', 'Bertanggung jawab dalam mencari mitra strategis atau pihak eksternal yang dapat mendukung pertumbuhan bisnis jangka panjang perusahaan', NULL, '8'),
(335, 'development_program', NULL, '2025-11-24 23:29:30', 'Mengadakan forum diskusi dengan subordinat untuk membahas mengenaiperformance dan dinamika tugas yang muncul selama ini. Minta ia menilai dirinya sendiri terkait performa dan selaraskan dengan target jangka panjang organisasi', NULL, '8'),
(336, 'development_program', NULL, '2025-11-24 20:10:00', 'Building a Sustainable Team Culture', NULL, '10'),
(337, 'development_program', NULL, '2025-11-24 03:31:59', 'Berbagi tips mengenai kiat-kiat menjaga keharmonisan dalam organisasi dan sharing terkait dengan pengalaman, tantangan serta inisiatif yang telah dilalui oleh atasan untuk mendukung keberhasilan jangka panjang organisasi.', NULL, '9'),
(338, 'development_program', NULL, '2025-11-25 00:46:19', 'Diberikan tanggung jawab untuk memetakan pihak-pihak potensial untuk bekerja sama, kemudian menyusun kegiatan yang relevan untuk mempererat hubungan dan interaksi dengan mitra', NULL, '8'),
(339, 'development_program', NULL, '2025-11-24 23:42:55', 'Mengikuti forum untuk menambah referensinya terkait trend bisnis di masa mendatang sebagai dasar penyusunan strategi dan inisiatif perusahaan yang dapat menudukung keberhasilan jangka panjang organisasi', NULL, '8'),
(341, 'development_program', NULL, '2025-11-24 19:22:24', 'Mengenalkan konsep dasar perubahan dalam organisasi dan bagaimana bersikap fleksibel dalam menghadapi perubahan kecil', NULL, '9'),
(342, 'development_program', NULL, '2025-11-24 19:20:04', 'Mengamati dan mencatat perubahan dalam proses kerja harian dan bagaimana menghadapinya', NULL, '8'),
(343, 'development_program', NULL, '2025-11-24 19:19:03', 'Helping Teams Adapt & Grow', NULL, '10'),
(344, 'development_program', NULL, '2025-11-24 19:19:46', 'Mengajak asesi untuk berdiskusi secara rutin terkait proses implementasi perubahan yang ada apakah ada kesulitan dalam mengikutinya', NULL, '9'),
(345, 'development_program', NULL, '2025-11-24 19:18:43', 'Mengikuti proyek atau inisiatif perubahan dalam perusahaan (misalnya implementasi sistem baru, restrukturisasi tim, atau perubahan kebijakan)', NULL, '8'),
(346, 'development_program', NULL, '2025-11-24 19:19:11', 'Managing & Innovating Through Change', NULL, '10'),
(350, 'development_program', NULL, '2025-12-30 09:25:24', 'Menganalisis proses kerja/studi kasus untuk mengidentifikasi peluang improvement serta menghasilkan ide-ide perbaikan secara sistematis dan strategis untuk menghasilkan ide inovasi', NULL, '8'),
(351, 'development_program', NULL, '2025-12-26 04:06:12', 'Mempraktikkan teknik-teknik manajemen stres ketika berada dalam situasi yang menekan untuk tetap fokus dan tenang, guna menjaga konsistensi performa diri dan tim dalam mencapai target organisasi', NULL, '8'),
(352, 'development_program', NULL, '2025-12-30 09:24:51', 'Menganalisis tren terbaru untuk mengeksplorasi proses baru dan melihat suatu hal dari berbagai perspektif untuk menghasilkan ide inovasi', NULL, '8'),
(353, 'development_program', NULL, '2025-11-24 19:22:40', 'Mengikuti event-event terkait inovasi yang menuntutnya untuk mempelajari kemampuan dalam menginisiasi suatu perbaikan secara mandiri dan mendapatkan bimbingan mentor untuk mengaplikasikan ide perbaikan yang digagas', NULL, '8'),
(354, 'development_program', NULL, '2025-11-24 20:59:18', 'Melakukan benchmark ke industri sejenis untuk mendapatkan gambaran dan referensi untuk menghasilkan ide inovasi', NULL, '8'),
(355, 'development_program', NULL, '2025-11-24 20:25:22', 'Strategic Change Management', NULL, '10'),
(356, 'development_program', NULL, '2025-11-24 20:09:41', 'Membahas strategi manajemen perubahan dalam organisasi dan bagaimana memastikan keberlanjutan perubahan yang telah diterapkan', NULL, '9'),
(357, 'development_program', NULL, '2025-12-29 04:21:54', 'Ditugaskan sebagai pemimpin proyek untuk merealisasikan ide inovasi bersama tim yang terdiri dari berbagai unit atau divisi. Diharapkan kemampuan dalam mengelola konflik tim dan mencapai tujuan bersama dapat meningkat', NULL, '8'),
(359, 'development_program', NULL, '2025-12-26 04:22:36', 'Self-Reflection & Personal Growth', NULL, '10'),
(360, 'development_program', NULL, '2025-11-24 23:26:41', 'Mendiskusikan mengenai pentingnya introspeksi diri dan continuous improvement dengan atasan dan melakukan pendekatan inovatif untuk mengelola kinerja tim yang disesuaikan dengan berbagai kondisi dan tantangan', NULL, '9'),
(361, 'development_program', NULL, '2025-11-24 23:48:12', 'Menyusun action plan sederhana untuk meningkatkan keterampilan dan kualitas kerja dan menganalisis feedback dari atasan dan rekan kerja untuk memahami aspek yang perlu diperbaiki', NULL, '8'),
(362, 'development_program', NULL, '2025-11-24 20:57:22', 'Seeking Feedback & Inspiring Effort', NULL, '10'),
(363, 'development_program', NULL, '2025-11-24 20:12:57', 'Dapat membahas dan memberikan umpan balik terkait performance dan dinamika tugas yang muncul selama ini. Minta ia menilai dirinya sendiri terkait performa dan selaraskan dengan tuntutan yang diberikan, baik secara teknis maupun non teknis', NULL, '9'),
(364, 'development_program', NULL, '2025-11-24 19:51:17', 'Berpartisipasi dalam forum atau komunitas untuk mendapatkan referensi dalam mempertahankan pencapaian target individu dan tim', NULL, '8'),
(365, 'development_program', NULL, '2025-11-24 20:55:32', 'Guiding, Motivating & Inspiring Creativity', NULL, '10'),
(366, 'development_program', NULL, '2025-11-24 23:39:50', 'Mengasah kemampuan untuk secara konsisten mempertahankan pencapaian target kerja bagi diri sendiri dan tim', NULL, '9'),
(368, 'development_program', NULL, '2025-12-26 04:23:51', 'Mendorong diri dan tim untuk tidak sekadar bekerja menyelesaikan tugas melainkan menghasilkan kinerja unggul guna memenuhi bahkan melampaui target', NULL, '9'),
(369, 'development_program', NULL, '2025-11-24 19:19:22', 'Memberikan bimbingan atau arahan untuk mendorong peningkatan kinerja anggota tim dalam memenuhi berbagai tuntutan pekerjaan maupun saat menghadapi perubahan', NULL, '9'),
(370, 'development_program', NULL, '2025-11-24 20:54:28', 'Exceeding Expectations Through Innovation', NULL, '10'),
(371, 'development_program', NULL, '2025-11-24 23:40:02', 'Mengasah kemampuan untuk secara konsisten mempertahankan pencapaian target kerja bagi diri sendiri dan tim, bahkan melampaui target yang diberikan', NULL, '9'),
(372, 'development_program', NULL, '2025-11-25 00:57:04', 'Melatih kemampuan untuk mengasah kemampuannya untuk dapat mendorong dan mengarahkan pihak-pihak yang menjadi timnya untuk memberikan usaha terbaik guna mencapai hasil kerja unggul melebihi ekspektasi', NULL, '9'),
(373, 'development_program', NULL, '2025-11-24 23:20:07', 'Memimpin proyek strategis yang menantang dan membutuhkan inovasi untuk mencapai target lebih tinggi dari ekspektasi awal dan Melakukan performance coaching kepada anggota tim untuk membantu mereka mencapai target yang lebih tinggi dari standar biasa', NULL, '8'),
(374, 'development_program', NULL, '2025-11-24 20:53:38', 'Effective Planning & Time Management', NULL, '10'),
(375, 'development_program', NULL, '2025-12-26 04:20:35', 'Membahas & menyusun daftar prioritas kerja harian dengan teknik sederhana seperti to-do list dan time blocking', NULL, '9'),
(376, 'development_program', NULL, '2025-11-24 23:16:32', 'Membuat weekly work plan yang mencakup pembagian tugas berdasarkan prioritas dan tenggat waktu, dan melakukan daily review setiap hari untuk melihat apakah target harian tercapai dan menyesuaikan strategi dengan alat bantu monitoring seperti Google Calendar, Trello, atau Planner untuk mengorganisir tugas dan memastikan semuanya berjalan sesuai rencana', NULL, '8'),
(377, 'development_program', NULL, '2025-11-24 20:53:51', 'Effective Work Planning & Execution', NULL, '10'),
(378, 'development_program', NULL, '2025-11-24 23:48:26', 'Menyusun rencana kerja secara sistematis disertai pengelolaan dan prioritas terhadap tugas, target, sumber daya', NULL, '9'),
