(616, 'development_program', '2026-01-21 03:44:36', '2026-01-21 03:44:36', 'Terlibat dalam suatu lingkungan baru (misalnya suatu project) yang kondisinya dinamis (terdapat perbedaan pendapat/konflik), serta ditugaskan untuk menjaga sinergi dan keharmonisan tim untuk jangka panjang yang melibatkan anggota tim untuk jangka panjang bisnis perusahaan', NULL, '8'),
(618, 'development_program', '2026-02-12 09:33:47', '2026-02-12 09:33:47', 'Membantu dan mendorong rekan kerja/tim dengan mengedepankan komunikasi dua arah dalam bekerja sama, membimbing guna mempertahankan semangat timnya', NULL, '9'),
(619, 'development_program', '2026-02-12 09:36:30', '2026-02-12 09:36:30', 'Memimpin suatu tim/rekan kerja dalam suatu kelompok dengan menggunakan komunikasi secara terbuka (2 arah) guna memperkuat sinergi dan kinerja bersama', NULL, '8'),
(620, 'development_program', '2026-02-12 09:51:23', '2026-02-12 09:51:23', 'Asertif dalam mengedukasi atau melakukan teguran pada pihak-pihak yang melakukan pelanggaran serta menyusun langkah antisipasi agar tidak terjadi pelanggaran berulang', NULL, '9'),
(621, 'development_program', '2026-02-12 09:54:45', '2026-02-12 09:54:45', 'Penugasan untuk melakukan observasi terhadap potensi dan/atau pelanggaran yang telah terjadi di lingkungan kerja serta memberikan teguran/edukasi pada pihak lain yang tidak menjalankan aturan/norma perusahaan', NULL, '8'),
(622, 'development_program', '2026-02-12 10:01:37', '2026-02-12 10:01:37', 'Mengadakan diskusi berkala dengan tim kerja baik dalam hal formal maupun informal guna menciptakan iklim harmonis serta mengkomunikasikan harapan dan arahan mengenai keselarasan kerja dengan orientasi jangka panjang perusahaan', NULL, '8'),
(623, 'development_program', '2026-02-12 10:08:16', '2026-02-12 10:08:16', 'Identifikasi suatu konflik atau perbedaan pandangan, disertai alternatif penyelesaiannya untuk menjembatani perbedaan atau konflik', NULL, '9'),
(624, 'development_program', '2026-02-12 10:10:23', '2026-02-12 10:10:23', 'Terlibat dalam suatu proyek dengan beragam karakteristik tim untuk mengasah kemampuannya dalam memfasilitasi perbedaan pandangan dari setiap pihak serta mengarahkan tim untuk senantiasa berorientasi pada sasaran jangka panjang organisasi', NULL, '8'),
(625, 'development_program', '2026-02-12 10:10:53', '2026-02-12 10:10:53', 'Berkonsultasi dengan atasan dan melakukan klarifikasi apabila terdapat suatu perubahan di lingkungan kerja guna mendapatkan informasi yang valid dan akurat terkait kebutuhan perubahan', NULL, '8'),
(626, 'development_program', '2026-02-12 10:14:22', '2026-02-12 10:14:22', 'Mengidentifikasi dan mengevaluasi proses/sistem kerja yang ada untuk melihat potensi perbaikan sebagai acuan dalam menghasilkan program inovasi/perbaikan yang dapat meningkatkan produktivitas', NULL, '9'),
(628, 'development_program', '2026-02-12 10:18:07', '2026-02-12 10:18:07', 'Melakukan pendampingan dan arahan guna membantu anggota tim mengembangkan kinerjanya sehingga mampu memenuhi beragam tuntutan pekerjaan dan mendorong peningkatan kinerja tim secara lebih optimal', NULL, '9'),
(629, 'development_program', '2026-02-12 10:19:53', '2026-02-12 10:19:53', 'Mendorong tim/rekan kerja untuk tidak hanya sekadar bekerja untuk mencapai target, melainkan secara konsisten dapat menghasilkan suatu hasil kerja yang unggul yang dapat memberikan nilai tambah bagi organisasi', NULL, '9'),
(630, 'development_program', '2026-02-12 10:20:52', '2026-02-12 10:20:52', 'Penugasan untuk merancang dan implementasi suatu project untuk jangka pendek-menengah yang menuntut suatu perencanaan dan monitoring yang detail (seperti sumber daya, identifikasi kebutuhan organisasi, hingga proses pengawasan)', NULL, '8'),
(631, 'development_program', '2026-02-12 10:21:17', '2026-02-12 10:21:17', 'Melakukan pendampingan dan arahan yang tepat untuk anggota tim guna membantu mereka meningkatkan kinerja dalam menghadapi berbagai tuntutan pekerjaan', NULL, '8'),
(632, 'development_program', '2026-02-12 10:21:58', '2026-02-12 10:21:58', 'Menjadi teladan bagi tim/rekan kerja dalam memberlakukan sasaran menantang bagi dirinya sendiri serta menunjukkan hasil nyata dalam menghasilkan pencapaian dan kinerja unggul secara konsisten', NULL, '9'),
(633, 'development_program', '2026-02-13 06:43:34', '2026-02-13 06:43:34', 'Assist and encourage colleagues or the team by prioritizing two-way communication, providing guidance to maintain team morale', NULL, '9'),
(634, 'development_program', '2026-02-13 06:45:54', '2026-02-13 06:45:54', 'Identify a conflict or difference of opinion, accompanied by alternative solutions to bridge the difference or conflict', NULL, '9'),
(635, 'development_program', '2026-02-13 06:46:13', '2026-02-13 06:46:13', 'Engage in a project with diverse team characteristics to hone the ability to facilitate differing views from all parties, and steer the team to remain consistently oriented towards the organization\'s long-term goals', NULL, '8'),
(636, 'development_program', '2026-02-13 06:46:47', '2026-02-13 06:46:47', 'Consult with superiors and seek clarification regarding changes in the work environment to obtain valid and accurate information about the change requirements', NULL, '8'),
(637, 'development_program', '2026-02-13 06:47:32', '2026-02-13 06:47:32', 'Identify and evaluate existing work processes or systems to determine potential improvements, serving as a reference for creating innovation or improvement programs that enhance productivity', NULL, '9'),
(638, 'development_program', '2026-02-13 06:47:56', '2026-02-13 06:47:56', 'Assignment to lead a project to initiate an improvement program, and realize it with a team consisting of various units or divisions', NULL, '8'),
(639, 'development_program', '2026-02-13 06:48:37', '2026-02-13 06:48:37', 'Encourage the team or colleagues not merely to work to achieve targets, but to consistently deliver superior results that provide added value to the organization', NULL, '9'),
(640, 'development_program', '2026-02-13 06:49:55', '2026-02-13 06:49:55', 'Provide coaching and guidance to help team members develop their performance, enabling them to meet various work demands and drive more optimal team performance improvement', NULL, '9'),
(641, 'development_program', '2026-02-13 06:51:03', '2026-02-13 06:51:03', 'Assignment to design and implement a short-to-medium term project requiring detailed planning and monitoring (such as resources, identification of organizational needs, and oversight processes)', NULL, '8'),
(642, 'development_program', '2026-02-13 06:51:33', '2026-02-13 06:51:33', 'Provide appropriate coaching and guidance to team members to help them improve their performance in meeting various work demands', NULL, '8'),
(643, 'development_program', '2026-02-13 06:51:56', '2026-02-13 06:51:56', 'Serve as a role model for the team or colleagues by setting challenging personal goals and demonstrating tangible results in consistently delivering superior achievements and performance', NULL, '9'),
